{
 "tur": "cevap",
 "cevap": [
  {
   "alintilar": [
    {
     "kaynak_no": 1,
     "metin": "Is the needle tip bent? Is the needle tip blunt? If the needle tip is bent or blunt, replace the needle."
    }
   ],
   "metin": "İğne ucu eğri mi veya kör mü kontrol edin; eğer eğri veya kör ise iğneyi değiştirin."
  },
  {
   "alintilar": [
    {
     "kaynak_no": 1,
     "metin": "Is the needle properly installed? If it is incorrect, install the needle correctly."
    }
   ],
   "metin": "İğnenin doğru takılıp takılmadığını kontrol edin; yanlış takılmışsa iğneyi doğru şekilde takın."
  },
  {
   "alintilar": [
    {
     "kaynak_no": 1,
     "metin": "Is the machine properly threaded? If it is incorrect, thread the thread correctly."
    }
   ],
   "metin": "Makinenin doğru şekilde ipliklenip ipliklenmediğini kontrol edin; yanlışsa ipliği doğru şekilde geçirin."
  },
  {
   "alintilar": [
    {
     "kaynak_no": 1,
     "metin": "Is the presser foot pressure too weak? Adjust the presser foot pressure."
    }
   ],
   "metin": "Baskı ayağı (presser foot) basıncı çok düşük mü kontrol edin ve basıncı ayarlayın."
  },
  {
   "alintilar": [
    {
     "kaynak_no": 1,
     "metin": "Is the needle too thin? Replace the needle with a needle that is one rank thicker."
    }
   ],
   "metin": "İğne çok ince mi kontrol edin; eğer inceyse bir derece daha kalın bir iğne ile değiştirin."
  },
  {
   "alintilar": [
    {
     "kaynak_no": 1,
     "metin": "Is the presser foot too high? Adjust the height of the presser foot."
    }
   ],
   "metin": "Baskı ayağı (presser foot) çok mu yüksek kontrol edin ve yüksekliğini ayarlayın."
  },
  {
   "alintilar": [
    {
     "kaynak_no": 1,
     "metin": "Is the thread take-up spring too weak? Adjust the tension of the thread take-up spring."
    }
   ],
   "metin": "İplik alıcı yay (thread take-up spring) çok mu zayıf kontrol edin ve yayın gerginliğini ayarlayın."
  },
  {
   "alintilar": [
    {
     "kaynak_no": 1,
     "metin": "Is the needle and rotary hook timing correct? Adjust the height of the needle bar. Adjust the clearance between the needle and the tip of the rotary='"}
   ],
   "metin": "İğne ve rotary hook (döner kanca) zamanlamasının doğru olup olmadığını kontrol edin; iğne çubuğu (needle bar) yüksekliğini ve iğne ile rotary hook ucu arasındaki boşluğu ayarlayın."
  }
 ],
 "sesli_metin": "S-7300B'de dikiş atlaması için iğneyi kontrol edin, iğne ucu eğri veya körse değiştirin. İğnenin doğru takıldığından ve ipliklemenin doğru yapıldığından emin olun. Baskı ayağı basıncını, yüksekliğini ve iplik alıcı yay gerginliğini ayarlayın. Ayrıca,"
  ,
 "celiski_var": false
}

aday_sorular:A074.ham:
{
 "tur": "cevap",
 "cevap": [
  {
   "alintilar": [
    {
     "kaynak_no": 2,
     "metin": "Problem: Skipped stitches at sewing start Thread unraveling at sewing start."
    }
   ],
   "metin": "Dikiş başlangıcında dikiş atlama ve iplik çözülmesi sorunu için aşağıdaki çözüm yolları uygulanabilir:"
  },
  {
   "alintilar": [
    {
     "kaynak_no": 2,
     "metin": "Is the thread take-up spring tension too strong? Reduce the tension of the thread take-up spring."
    }
   ],
   "metin": "İplik alıcı yay (thread take-up spring) tansiyonu çok güçlü ise iplik alıcı yayın tansiyonunu azaltın."
  },
  {
   "alintilar": [
    {
     "kaynak_no": 2,
     "metin": "Is the thread take-up spring operating range too large? Lower the position of the thread take-up spring."
    }
   ],
   "metin": "İplik alıcı yayın (thread take-up spring) çalışma aralığı çok geniş ise iplik alıcı yayın konumunu aşağı indirin."
  },
  {
   "alintilar": [
    {
     "kaynak_no": 2,
     "metin": "Is the trailing length of the upper thread too short after thread trimming? Adjust the pretension."
    }
   ],
   "metin": "İplik kesme sonrası üst iplik payı çok kısa ise ön tansiyonu (pretension) ayarlayın."
  },
  {
   "alintilar": [
    {
     "kaynak_no": 2,
     "metin": "Are the threads not being trimmed cleanly? Sharpen the fixed knives, or replace the fixed and movable knives if necessary. Replace the movable knife."
    }
   ],
   "metin": "İplikler temiz kesilmiyorsa sabit bıçakları bileyin veya gerekirse sabit ve hareketli bıçakları değiştirin; hareketli bıçağı değiştirin."
  },
  {
   "alintilar": [
    {
     "kaynak_no": 2,
     "metin": "Is the needle too thick? Replace the needle with a needle that is one rank thinner."
    }
   ],
   "metin": "İğne çok kalın ise iğneyi bir derece daha ince bir iğne ile değiştirin."
  },
  {
   "alintilar": [
    {
     "kaynak_no": 2,
     "metin": "Is the length of thread trailing out from the bobbin case after thread trimming too short If the bobbin is spinning loosely, replace the anti-spin way"
    }
   ],
   "metin": "İplik kesme sonrası masura kutusundan çıkan iplik uzunluğu çok kısa ise ve masura gevşek dönüyorsa, masura kutusundaki anti-spin yayını değiştirin."
  },
  {
   "alintilar": [
    {
     "kaynak_no": 2,
     "metin": "Is the sewing speed too fast at the sewing start? Use the slow start key."
    }
   ],
   "metin": "Dikiş başlangıcında dikiş hızı çok hızlı ise yavaş başlatma (slow start) tuşunu kullanın."
  }
 ],
 "sesli_metin": "Dikiş başlangıcındaki atlama ve iplik çözülmesi için iplik alıcı yay tansiyonunu azaltın, iplik alıcı yayın konumunu düşürün, ön tansiyonu ayarlayın, bıçakları bileyin veya değiştirin, daha ince iğne kullanın veya anti-spin yayını değiştirin ve yavaş"
,
 "celiski_var": false
}

